package com.loopers.application.queue;import com.loopers.infrastructure.queue.RedisAdmissionStore;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.data.redis.connection.lettuce.LettuceConnectionFactory;import org.springframework.data.redis.core.RedisTemplate;import org.springframework.data.redis.serializer.StringRedisSerializer;import java.util.concurrent.*;import static org.assertj.core.api.Assertions.assertThat;
@SpringBootTest class QueueCapacityTest{@Autowired AdmissionService service;@Autowired RedisAdmissionStore store;@AfterEach void clean(){store.clear();}@Test void capacityDuplicateAndTerminalReleaseAreAtomic(){assertThat(service.admit("w1",3)).isEqualTo(AdmissionService.Result.ACCEPTED);assertThat(service.admit("w1",3)).isEqualTo(AdmissionService.Result.ACCEPTED);assertThat(service.admit("w2",3)).isEqualTo(AdmissionService.Result.ACCEPTED);assertThat(service.admit("w3",3)).isEqualTo(AdmissionService.Result.ACCEPTED);assertThat(service.admit("w4",3)).isEqualTo(AdmissionService.Result.REJECTED);assertThat(store.pending()).isEqualTo(3);service.completed("w2");assertThat(service.admit("w4",3)).isEqualTo(AdmissionService.Result.ACCEPTED);service.failed("w3");assertThat(store.pending()).isEqualTo(2);}@Test void twoRequestsForLastSlotAcceptExactlyOne()throws Exception{service.admit("w1",3);service.admit("w2",3);CountDownLatch start=new CountDownLatch(1);try(ExecutorService p=Executors.newFixedThreadPool(2)){Future<AdmissionService.Result>a=p.submit(()->{start.await();return service.admit("w3",3);});Future<AdmissionService.Result>b=p.submit(()->{start.await();return service.admit("w4",3);});start.countDown();assertThat(java.util.List.of(a.get(),b.get()).stream().filter(x->x==AdmissionService.Result.ACCEPTED).count()).isEqualTo(1);}}@Test void totalRedisOutageFailsClosed(){LettuceConnectionFactory f=new LettuceConnectionFactory("127.0.0.1",1);f.afterPropertiesSet();RedisTemplate<String,String>r=new RedisTemplate<>();r.setConnectionFactory(f);r.setKeySerializer(new StringRedisSerializer());r.setValueSerializer(new StringRedisSerializer());r.setHashKeySerializer(new StringRedisSerializer());r.setHashValueSerializer(new StringRedisSerializer());r.afterPropertiesSet();try{assertThat(new AdmissionService(new RedisAdmissionStore(r)).admit("w1",3)).isEqualTo(AdmissionService.Result.REJECTED);}finally{f.destroy();}}}
